		db:                   db,
		dbPath:               cfg.Path,
		beadsDir:             beadsDir,
		database:             cfg.Database,
		connStr:              connStr,
		breaker:              breaker,
		committerName:        cfg.CommitterName,
		committerEmail:       cfg.CommitterEmail,
		remote:               cfg.Remote,
		branch:               "main",
		remoteUser:           cfg.RemoteUser,
		remotePassword:       cfg.RemotePassword,
		serverMode:           true,
